struct MedianFinder {
    private var low = Heap<Int>(>)    // max-heap
    private var high = Heap<Int>(<)   // min-heap

    mutating func addNum(_ num: Int) {
        low.push(num)
        high.push(low.pop()!)
        if high.count > low.count { low.push(high.pop()!) }
    }
    func findMedian() -> Double {
        low.count > high.count ? Double(low.top!) : Double(low.top! + high.top!) / 2
    }
}
